#include <stdio.h>

int count_positive(const int *values, int length) {
    int count = 0;
    for (int index = 0; index < length; index += 1) {
        if (values[index] > 0) {
            count += 1;
        }
    }
    return count;
}

int main(void) {
    int values[] = { 3, -1, 2 };
    printf("%d\n", count_positive(values, 3));
    return 0;
}
